import{c as a,Q as i,j as t,m as r}from"./chunks/framework.DOi4mjdC.js";const l="/assets/%E7%BA%BF%E7%A8%8B%E6%9E%B6%E6%9E%84.BVSdcKVc.png",d="/assets/%E7%BA%BF%E7%A8%8B%E6%9E%B6%E6%9E%84-8.Hhgs0b6g.png",h=JSON.parse('{"title":"线程架构","description":"","frontmatter":{},"headers":[{"level":1,"title":"线程架构","slug":"线程架构"}],"relativePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/线程架构.md","filePath":"guide/编程指南/编程模型/AI-Core-SIMT编程/线程架构.md"}'),o={name:"guide/编程指南/编程模型/AI-Core-SIMT编程/线程架构.md"};function s(p,e,m,c,n,_){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="线程架构" tabindex="-1">线程架构 <a class="header-anchor" href="#线程架构" aria-label="Permalink to &quot;线程架构&quot;">​</a></h1><p>SIMT编程模型的线程层次结构分为两层：</p><ul><li>线程块网格（Grid）：由多个线程块（Thread Block）组成，使用内置变量<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li20760123812911">gridDim</a>来表示启用的线程块的个数，同一时刻一个AIV核只执行一个线程块任务。</li><li>线程块（Thread Block）：由若干线程（thread）组成，使用内置变量<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li076017381191">blockDim</a>表示一个线程块启用的的线程个数，一个线程块最多可以启用2048个线程。</li></ul><p>基于SIMT编程模型的程序，在AIV核上执行多个结构相同的线程块，执行的总线程数等于gridDim*blockDim。</p><p><img src="'+l+'" alt=""></p><p>gridDim由三维结构<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li1136665405">dim3</a>来表示，{dimx，dimy，dimz}用于指定3个不同维度的线程块的大小，三维乘积的总数不超过65535，各线程块可通过线程块索引<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li1676053814914">blockIdx</a>进行标识。blockDim也由dim3三维结构表示，三维乘积的总数不超过2048，各线程可通过线程块内线程索引<a href="./../../语言扩展层/SIMT-BuiltIn关键字.html#li7760123814919">threadIdx</a>进行标识。线程索引的计算示例如下图所示：</p><p><img src="'+d+'" alt=""></p><p>底层调度过程中，同一时刻一个AIV只能执行一个线程块任务，每个线程块会被切分成多个Warp依次调度并完成执行。Warp是执行相同指令的线程的集合，每个Warp包含32个线程。每个AIV核包含4个Warp调度器（Warp Scheduler），调度器编号scheduler id为warp id % 4。</p>',8)])])}const u=a(o,[["render",s]]);export{h as __pageData,u as default};
